int fan_fd = 5; // fanotify file descriptor
const char *target_path = "/home/user/data/";

uint64_t events = FAN_ACCESS | FAN_MODIFY;

// 1. Add mark to target_path, following symlinks
fanotify_mark(fan_fd, FAN_MARK_ADD,
              events, AT_FDCWD, target_path);

// 2. Modify existing mark (Change events, keep options)
fanotify_mark(fan_fd, FAN_MARK_ADD | FAN_MARK_EVICTABLE,
              FAN_MOVE | FAN_DELETE, AT_FDCWD, target_path);

// 3. Remove mark completely
fanotify_mark(fan_fd, FAN_MARK_REMOVE,
              0, AT_FDCWD, target_path);
